import com.mushafi.app.*;import org.json.*;import java.util.*;import java.nio.file.*;import java.lang.reflect.*;
public final class PrayerSourceTest {
 static void need(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 static void rejects(JSONObject data,PrayerSettings s,String month)throws Exception{boolean rejected=false;try{PrayerRemoteSource.parseCalendar(data,s,month);}catch(Exception expected){rejected=true;}need(rejected,"invalid response accepted");}
 public static void main(String[] args)throws Exception{
  Field cache=PrayerRemoteSource.class.getDeclaredField("cache");cache.setAccessible(true);int cities=0,days=0;
  try(java.util.stream.Stream<Path> files=Files.list(Paths.get(args[0]))){for(Path file:(Iterable<Path>)files.filter(p->p.toString().endsWith(".json"))::iterator){JSONObject fixture=new JSONObject(new String(Files.readAllBytes(file),"UTF-8")),request=fixture.getJSONObject("request"),payload=fixture.getJSONObject("response");PrayerSettings s=new PrayerSettings(new JSONObject().put("method","AUTO").put("confirmed",true).put("latitude",request.getDouble("latitude")).put("longitude",request.getDouble("longitude")).put("timezone",request.getString("timezone")).put("asr",request.optInt("school")==1?"HANAFI":"SHAFI"));
   JSONObject rows=PrayerRemoteSource.parseCalendar(payload,s,request.getString("month"));JSONObject saved=new JSONObject().put("profile","AUTO|"+s.json.getString("asr")+"|"+s.json.getString("timezone")).put("latitude",s.json.getDouble("latitude")).put("longitude",s.json.getDouble("longitude")).put("fetchedAt",1).put("days",rows);cache.set(null,saved);
   for(Iterator<String> keys=rows.keys();keys.hasNext();){String key=keys.next();String[] parts=key.split("-");Calendar date=new GregorianCalendar(TimeZone.getTimeZone(s.json.getString("timezone")),Locale.US);date.clear();date.set(Integer.parseInt(parts[0]),Integer.parseInt(parts[1])-1,Integer.parseInt(parts[2]),12,0);JSONObject actual=PrayerCalculator.calculate(s,date),expected=rows.getJSONObject(key);need(actual.getString("source").equals("aladhan"),"source not used "+file);for(String name:new String[]{"fajr","sunrise","dhuhr","asr","maghrib","isha"}){need(actual.getLong(name)==expected.getLong(name),"time mismatch "+key+" "+name);need(actual.getLong(name)%60000==0,"fractional minute");}need(actual.getLong("duha")==actual.getLong("sunrise")+900000,"duha not based on selected source");days++;}
   JSONObject rejected=new JSONObject(payload.toString());rejected.getJSONArray("data").remove(0);rejects(rejected,s,request.getString("month"));rejected=new JSONObject(payload.toString());rejected.getJSONArray("data").getJSONObject(0).getJSONObject("meta").put("latitude",0);rejects(rejected,s,request.getString("month"));rejected=new JSONObject(payload.toString());rejected.getJSONArray("data").getJSONObject(0).getJSONObject("timings").put("Fajr","NaN");rejects(rejected,s,request.getString("month"));rejected=new JSONObject(payload.toString());rejected.getJSONArray("data").put(1,rejected.getJSONArray("data").getJSONObject(0));rejects(rejected,s,request.getString("month"));String originalSchool=s.json.getString("asr");s.json.put("asr",originalSchool.equals("SHAFI")?"HANAFI":"SHAFI");rejects(payload,s,request.getString("month"));s.json.put("asr",originalSchool);
   String dateKey=rows.keys().next();String[] parts=dateKey.split("-");Calendar date=new GregorianCalendar(TimeZone.getTimeZone(s.json.getString("timezone")),Locale.US);date.clear();date.set(Integer.parseInt(parts[0]),Integer.parseInt(parts[1])-1,Integer.parseInt(parts[2]),12,0);s.json.put("onlineSource",false);need(PrayerRemoteSource.day(s,date)==null,"offline switch ignored");s.json.put("onlineSource",true).put("latitude",s.json.getDouble("latitude")+1);need(PrayerRemoteSource.day(s,date)==null,"wrong location cache used");s.json.put("latitude",request.getDouble("latitude"));s.json.getJSONObject("offsets").put("fajr",3);need(PrayerRemoteSource.day(s,date).getLong("fajr")==rows.getJSONObject(dateKey).getLong("fajr")+180000,"custom offset lost");need(s.row("asr").getInt("iqama")==20,"Asr iqama lost");cities++;
   if(file.getFileName().toString().equals("riyadh.json")){Calendar oct=new GregorianCalendar(TimeZone.getTimeZone("Asia/Riyadh"),Locale.US);oct.clear();oct.set(2026,9,30,12,0);s.json.getJSONObject("offsets").put("fajr",0);JSONObject day=PrayerRemoteSource.day(s,oct);need(day.getLong("fajr")==1793324400000L,"Riyadh fixed UTC comparison");s.json.put("ramadan","on");need(PrayerRemoteSource.day(s,oct).getLong("isha")-day.getLong("maghrib")==7200000,"Ramadan on override");s.json.put("ramadan","off");need(PrayerRemoteSource.day(s,oct).getLong("isha")-day.getLong("maghrib")==5400000,"Ramadan off override");}
  }}
  need(cities==13,"missing city fixtures");cache.set(null,new JSONObject());PrayerSettings local=new PrayerSettings(new JSONObject().put("method","AUTO").put("onlineSource",false).put("ramadan","off"));need(PrayerCalculator.day(local,1793347200000L,0).get(Calendar.YEAR)==2026,"locale changed Gregorian prayer year");JSONObject fallback=PrayerCalculator.calculate(local,PrayerCalculator.day(local,1793347200000L,0));need(fallback.getString("source").equals("offline"),"fallback missing");for(String name:new String[]{"fajr","sunrise","dhuhr","asr","maghrib","isha"})need(fallback.getLong(name)%60000==0,"native fallback millisecond rounding");
  System.out.println("PASS: "+cities+" city/method datasets, "+days+" daily source rows, offsets/iqama, cache location/settings isolation, source off/fallback, Ramadan overrides, DST ISO timestamps, overnight Isha, malformed/incomplete/duplicate responses and native minute rounding.");
 }
}
